"""Persist explicit parent assessments after complete displayed source reads."""
import hashlib
import json
from pathlib import Path

R = Path(__file__).resolve().parents[2]
P = R / 'dag/reviews/additional_rust_linear_algebra_remaining'
notes_path = Path(str(P) + '_notes.json')
notes = json.loads(notes_path.read_bytes())
scope = json.loads(Path(str(P) + '_scope.json').read_bytes())
pins = {x['path']: x['sha256'] for x in scope['files']}

assessments = {
    'src/basic_matrix_serde.rs': 'Read all148 lines. The three-field rows/cols/data wire denies unknown fields and routes deserialization through checked row-major construction, preserving shape/storage equality. Wire parsing and allocation occur before that constructor and have no resource quota here. The remaining capacity metadata and tests concern counts, not serialization or algebraic correctness. No original execution.',
    'src/backend/mod.rs': 'Read all172 lines. Introductory private-backend prose is stale: lib.rs publicly exports backend and this file publicly exports basic_matrix. PermutationTrace admits an actual square binary matrix of degree1..64, verifies exactly one unit per row and column and counts fixed points, giving the usual finite permutation trace. Its result stores degree/count rather than binding to the original matrix. The two tests are substantive finite examples, not a new execution receipt.',
    'src/backend/basic_matrix.rs': 'Read all1468 lines in four contiguous displayed ranges. Private rows/cols/data and checked product/length construction preserve rectangular storage; bounded indexing and shape checks make finite matrix operations meaningful. Ordinary Numeric explicitly allows overflow/nonfinite behavior; CheckedNumeric uses fallible scalar operations whose laws and callback behavior remain assumptions. Rational64 checked operations widen before normalization and refuse zero denominators or unrepresentable canonical outputs. OperationLimits preflights element counts and exact multiply/add call counts, not elapsed time or arbitrary-precision scalar memory. Generators check shape/limits/reservation before callbacks; zero-area cases do not loop over huge empty row dimensions. Checked matrix multiplication follows ordered dot products and may refuse an intermediate overflow even when the final mathematical sum would fit. Tests cover useful shape, arithmetic, zero, conversion and overflow boundaries, but none was run here; historical mutation comments are not fresh receipts. No new defect asserted.',
    'src/exact_ldlt.rs': 'Read all286 lines. Rational LDLT admits nonempty square symmetric input and uses exact Schur updates. Positive pivots proceed; zero pivots require zero residual coupling; negative or coupled-zero pivots return a negative PSD decision with partial factors, not a complete inertia decomposition. The separate is_psd helper treats empty input as PSD and explicitly requires caller-supplied symmetry, so absence of its own symmetry test is not concealed. Under that premise, a nonzero coupling at a zero diagonal gives a negative2x2 principal minor. Independent exact controls compare759 symmetric matrices of sizes1..3 to all principal minors and reconstruct32 complete positive decompositions. Capacity boilerplate does not itself test LDLT; no original execution.',
    'src/exact_repair.rs': 'Read all264 lines. Public ExactRepairSpace rank/ambient/basis fields and constructors record unchecked metadata: with_basis counts vectors without checking independence, equal lengths, or a map image. Duplicate vectors give stored rank2 but actual rank1. This is separate from private ExactRepair, whose constructor and deserializer enforce dimensions and whose exact-class method actually checks omega-d0*alpha=0. That is a supplied finite image witness, with no d1 chain law, optimality, or semantic repair guarantee. Zero-edge/nonempty-vertex input legitimately represents the empty map. Embedded malformed-wire, residual and round-trip tests are useful but not executed.',
    'src/linear_algebra/image_kernel.rs': 'Read all1058 lines in three contiguous displayed ranges. Sealed checked exact fields support ordinary leftmost-pivot Gauss-Jordan reduction with typed arithmetic refusal. Image vectors are original pivot columns; kernel vectors correspond to free coordinates. Private RankRref and RawSubspaceBasis record computed outputs but do not bind the two values to one source matrix. Image membership compares augmented rank, constructs a free-zero particular solution and replays A*x=t before returning its witness; public output DTOs are not unforgeable capabilities. Unbounded allocations and unchecked augmented size arithmetic have no universal resource guarantee. Independent models compare831 small matrices with determinant-minor ranks and729 membership cases with augmented rank and replay. Tests contain real shape, overflow, kernel and in/out examples; render-only replay text is explicitly not execution evidence. No original/native run.',
    'src/image_kernel.rs': 'Read all124 lines and now also the entire canonical image/kernel owner. admit_rank_nullity checks pivot count/order/range and rank plus supplied kernel list length equals supplied columns. It neither binds the two private values to the same original matrix nor compares supplied columns to reduced-matrix width. Both values can legitimately be constructed from different sources: A=[1,0] and kernel of B=[0,1] pass the count checks although A*(1,0)=1. A second example passes declared columns3 for a1-column RREF and a2-column zero-map kernel. These countermodels refute common-source witness interpretation, not the numerical rank-nullity theorem. The sole embedded positive uses consistent inputs. No native execution.'
}
for name, assessment in assessments.items():
    notes['files'][name] = {'full_source_read': True, 'assessment': assessment}

def ev(name, lo, hi):
    path = 'code/rust/core_linear_algebra/' + name
    return {'path': path, 'sha256': pins[path], 'lines': [lo, hi]}

claims = [
    {'id': 'RLA-C05', 'statement': 'The matrix owner enforces rectangular storage and provides separately fallible arithmetic with preflight element and operation-count limits. Exact interpretation still requires lawful scalar operations, representable intermediates and available resources; its limits are not elapsed-time or arbitrary scalar-memory bounds.', 'evidence': [ev('src/backend/basic_matrix.rs', 143, 167), ev('src/backend/basic_matrix.rs', 238, 337), ev('src/backend/basic_matrix.rs', 350, 394), ev('src/backend/basic_matrix.rs', 846, 875), ev('src/basic_matrix_serde.rs', 7, 29)], 'limits': 'Source review only; no original execution or proof of external scalar implementations.'},
    {'id': 'RLA-C06', 'statement': 'The canonical exact image/kernel owner implements finite Gauss-Jordan reduction, basis extraction and a replayed particular image witness. Independent rational controls agree with determinant-minor rank and augmented-rank membership over the bounded panel.', 'evidence': [ev('src/linear_algebra/image_kernel.rs', 207, 279), ev('src/linear_algebra/image_kernel.rs', 308, 357), ev('src/linear_algebra/image_kernel.rs', 411, 477)], 'controls': ['RLA-P04'], 'limits': 'Finite independent model, not original Rust execution, a universal resource bound or a semantic natural-language certificate.'},
    {'id': 'RLA-C07', 'statement': 'The rational symmetric LDLT path supplies a substantive finite PSD decision under explicit shape, symmetry and exact-arithmetic premises. The private ExactRepair owner separately replays a supplied potential against its finite linear residual; neither mechanism infers its application semantics.', 'evidence': [ev('src/exact_ldlt.rs', 30, 168), ev('src/exact_repair.rs', 66, 138)], 'controls': ['RLA-P05'], 'limits': 'Failed PSD paths can contain partial factors; independent finite controls are not original execution. ExactRepair does not assert a full cochain complex or optimization result.'}
]
findings = [
    {'id': 'RLA-F01', 'statement': 'RankNullity admission accepts a reduced matrix and kernel from different matrices, and a declared column count different from the reduced width. Its count certificate cannot certify that the supplied vectors form the kernel of the supplied matrix.', 'evidence': [ev('src/image_kernel.rs', 1, 124), ev('src/linear_algebra/image_kernel.rs', 129, 177), ev('src/linear_algebra/image_kernel.rs', 207, 279)], 'controls': ['RLA-P06'], 'limits': 'Independent exact model of constructible outputs; no native execution. The rank-nullity theorem is unaffected.', 'recommended_action': 'Derive both values from one admitted matrix, or bind and validate source dimensions/content plus kernel annihilation and independence before asserting a common-source certificate.'},
    {'id': 'RLA-F02', 'statement': 'ExactRepairSpace counts an arbitrary supplied vector list as rank without checking independence or rectangular shape. Two copies of (1,0) are stored with rank2 although their span has dimension1.', 'evidence': [ev('src/exact_repair.rs', 18, 44)], 'controls': ['RLA-P07'], 'limits': 'Public metadata path only. This does not bypass the separate private ExactRepair residual replay.', 'recommended_action': 'Name these fields as declarations, or compute and check a basis for a bound source matrix before using them as mathematical rank or repair-space evidence.'}
]
for group, additions in [('claims', claims), ('findings', findings)]:
    ids = {x['id'] for x in additions}
    notes[group] = [x for x in notes[group] if x['id'] not in ids] + additions
receipt = Path(str(P) + '_controls02.json')
result = json.loads(receipt.read_bytes())
assert result['status'] == 'finite_controls_pass'
assert hashlib.sha256(receipt.with_suffix('.py').read_bytes()).hexdigest() == result['helper_sha256']
ids = {x['id'] for x in result['controls']}
notes['controls'] = [x for x in notes['controls'] if x['id'] not in ids]
for control in result['controls']:
    notes['controls'].append({**control, 'receipt': {'path': receipt.relative_to(R).as_posix(), 'sha256': hashlib.sha256(receipt.read_bytes()).hexdigest()}})
notes_path.write_text(json.dumps(notes, indent=2, ensure_ascii=False) + '\n', encoding='utf8')
print('Persisted six newly reviewed bodies, three claims, two scoped findings and four controls.')
